func (t *AutomataTomTerm) CompareTo(o any) int {
	ao := o.(TomTerm)
	if ao == TomTerm(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*AutomataTomTerm)
	if c := t.Options.CompareTo(tco.Options); c != 0 {
		return c
	}
	if c := t.Constraint.CompareTo(tco.Constraint); c != 0 {
		return c
	}
	if c := t.NumberList.CompareTo(tco.NumberList); c != 0 {
		return c
	}
	if c := t.Inst.CompareTo(tco.Inst); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *AutomataTomTerm) CompareToLPO(o any) int {
	ao := o.(TomTerm)
	if ao == TomTerm(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*AutomataTomTerm)
	if c := t.Options.CompareToLPO(tco.Options); c != 0 {
		return c
	}
	if c := t.Constraint.CompareToLPO(tco.Constraint); c != 0 {
		return c
	}
	if c := t.NumberList.CompareToLPO(tco.NumberList); c != 0 {
		return c
	}
	if c := t.Inst.CompareToLPO(tco.Inst); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

