// fromTermAutomataTomTerm is Java Gom's Automata.fromTerm: an unquoted application of
// Automata whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermAutomataTomTerm(trm aterm.ATerm, conv aterm.ATermConverter) (TomTerm, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "Automata" && !appl.GetAFun().IsQuoted() {
		return MakeAutomata(OptionListFromTermConv(appl.GetArgument(0), conv), ConstraintFromTermConv(appl.GetArgument(1), conv), TomNumberListFromTermConv(appl.GetArgument(2), conv), InstructionFromTermConv(appl.GetArgument(3), conv)), true
	}
	return nil, false
}

