// ConcTomTermTomList is the term type of the variadic operator `concTomTerm(...)` of sort TomList
// (Java's abstract class concTomTerm): a maximally-shared cons cell (Java's
// ConsconcTomTerm: a head and a tail) or the empty list (Java's EmptyconcTomTerm).
type ConcTomTermTomList struct {
	head  TomTerm
	tail  TomList
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*ConcTomTermTomList) isTomList() {}

func (t *ConcTomTermTomList) Hash() uint32 { return t.hash }

func (t *ConcTomTermTomList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcTomTermTomList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *ConcTomTermTomList) Duplicate() sharedobjects.Term {
	return &ConcTomTermTomList{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new TomTerm[]{}): a last tail
// that is not a list (of sort TomList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcTomTermTomList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur TomList = t
	for {
		c, ok := cur.(*ConcTomTermTomList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcTomTermTomList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concTomTerm list is not a TomTerm", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcTomTermTomList) ChildCount() int { return len(t.elements()) }

func (t *ConcTomTermTomList) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcTomTermTomList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcTomTermTomList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcTomTermFromArray(children).
func (t *ConcTomTermTomList) SetChildren(children []any) any {
	args := make([]TomTerm, len(children))
	for i, c := range children {
		args[i] = c.(TomTerm)
	}
	return MakeConcTomTerm(args...)
}

func (t *ConcTomTermTomList) String() string {
	var b strings.Builder
	b.WriteString("concTomTerm(")
	var cur TomList = t
	for {
		c, ok := cur.(*ConcTomTermTomList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsConcTomTerm is Java Gom's ConsconcTomTerm.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsConcTomTerm(head TomTerm, tail TomList) TomList {
	proto := &ConcTomTermTomList{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsconcTomTerm"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*ConcTomTermTomList)
}

// realMakeEmptyConcTomTerm is Java Gom's EmptyconcTomTerm.realMake: the shared empty list,
// without hook.
func realMakeEmptyConcTomTerm() TomList {
	proto := &ConcTomTermTomList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyconcTomTerm"), nil)}
	return factory.Build(proto).(*ConcTomTermTomList)
}

// RawConcTomTerm builds the concTomTerm list holding exactly args, without construction
// hook.
func RawConcTomTerm(args ...TomTerm) TomList {
	l := realMakeEmptyConcTomTerm()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsConcTomTerm(args[i], l)
	}
	return l
}

// EmptyConcTomTerm is Java Gom's EmptyconcTomTerm.make(): the empty concTomTerm list, after the
// construction hooks.
func EmptyConcTomTerm() TomList {
	return realMakeEmptyConcTomTerm()
}

// ConsConcTomTerm is Java Gom's ConsconcTomTerm.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "" first).
func ConsConcTomTerm(head TomTerm, tail TomList) TomList {
	return RealMakeConsConcTomTerm(head, tail)
}

// MakeConcTomTerm builds the list of args as Tom's `concTomTerm(args…)` does: from EmptyConcTomTerm,
// by ConsConcTomTerm, through the construction hooks (Java's concTomTerm.fromArray).
func MakeConcTomTerm(args ...TomTerm) TomList {
	var l TomList = EmptyConcTomTerm()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsConcTomTerm(args[i], l)
	}
	return l
}

// ConcTomTermFromArray is Java Gom's concTomTerm.fromArray(array).
func ConcTomTermFromArray(array []TomTerm) TomList { return MakeConcTomTerm(array...) }

// IsConcTomTerm is the `Is_concTomTerm` predicate strategy: succeeds (returns subject
// unchanged) when subject has the `concTomTerm` shape, otherwise fails with
// sl.ErrVisitFailure.
type IsConcTomTerm struct{ sl.AbstractStrategy }

func (IsConcTomTerm) VisitLight(subject any, _ sl.Introspector) (any, error) {
	if _, ok := subject.(*ConcTomTermTomList); ok {
		return subject, nil
	}
	return subject, sl.ErrVisitFailure
}
func (IsConcTomTerm) ChildCount() int             { return 0 }
func (IsConcTomTerm) ChildAt(int) sl.Strategy     { panic("IsConcTomTerm: no children") }
func (IsConcTomTerm) SetChildAt(int, sl.Strategy) { panic("IsConcTomTerm: no children") }
func (s *IsConcTomTerm) VisitEnv(sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*ConcTomTermTomList); ok {
		return sl.StatusSuccess
	}
	return sl.StatusFailure
}
func (s *IsConcTomTerm) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *IsConcTomTerm) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*IsConcTomTerm)(nil)

// VisitConcTomTerm is the `_concTomTerm` slot-visit strategy: when subject is `concTomTerm`,
// applies each constituent strategy to the matching child slot and
// rebuilds the term iff at least one child changed. Fails with
// sl.ErrVisitFailure when subject isn't `concTomTerm`.
type VisitConcTomTerm struct {
	sl.AbstractStrategy
	args []sl.Strategy
}

// NewVisitConcTomTerm builds the slot-visit strategy with the supplied per-slot
// sub-strategies.
func NewVisitConcTomTerm(args ...sl.Strategy) *VisitConcTomTerm {
	return &VisitConcTomTerm{args: args}
}

func (s *VisitConcTomTerm) VisitLight(subject any, intro sl.Introspector) (any, error) {
	if _, ok := subject.(*ConcTomTermTomList); !ok {
		return subject, sl.ErrVisitFailure
	}
	// Variadic alt: visit every element with args[0] (Java's
	// `_concX` invokes the sub-strategy on each list element).
	if len(s.args) == 0 {
		return subject, nil
	}
	count := intro.GetChildCount(subject)
	var newChildren []any
	for i := 0; i < count; i++ {
		oldChild := intro.GetChildAt(subject, i)
		newChild, err := s.args[0].VisitLight(oldChild, intro)
		if err != nil {
			return subject, err
		}
		if newChildren != nil {
			newChildren[i] = newChild
		} else if newChild != oldChild {
			newChildren = intro.GetChildren(subject)
			newChildren[i] = newChild
		}
	}
	if newChildren != nil {
		return intro.SetChildren(subject, newChildren), nil
	}
	return subject, nil
}

func (s *VisitConcTomTerm) ChildCount() int                 { return len(s.args) }
func (s *VisitConcTomTerm) ChildAt(i int) sl.Strategy       { return s.args[i] }
func (s *VisitConcTomTerm) SetChildAt(i int, v sl.Strategy) { s.args[i] = v }

func (s *VisitConcTomTerm) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*ConcTomTermTomList); !ok {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, true)
}
func (s *VisitConcTomTerm) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *VisitConcTomTerm) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*VisitConcTomTerm)(nil)

// SymbolName is the symbol of the Java term: ConsconcTomTerm or EmptyconcTomTerm.
func (t *ConcTomTermTomList) SymbolName() string {
	if t.empty {
		return "EmptyconcTomTerm"
	}
	return "ConsconcTomTerm"
}

func (t *ConcTomTermTomList) IsConsconcTomTerm() bool  { return !t.empty }
func (t *ConcTomTermTomList) IsEmptyconcTomTerm() bool { return t.empty }

func (t *ConcTomTermTomList) GetHeadconcTomTerm() TomTerm {
	if t.empty {
		panic(&aterm.GomError{Msg: "This TomList has no HeadconcTomTerm"})
	}
	return t.head
}
func (t *ConcTomTermTomList) GetTailconcTomTerm() TomList {
	if t.empty {
		panic(&aterm.GomError{Msg: "This TomList has no TailconcTomTerm"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a concTomTerm list counts as one element).
func (t *ConcTomTermTomList) Length() int {
	res := 0
	var tl TomList = t
	for {
		c, ok := tl.(*ConcTomTermTomList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcTomTermTomList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a concTomTerm list.
func (t *ConcTomTermTomList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur TomList = t
	for {
		c, ok := cur.(*ConcTomTermTomList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcTomTermTomList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcTomTerm
// (through the hooks).
func (t *ConcTomTermTomList) Reverse() TomList {
	if t.empty {
		return t
	}
	var cur TomList = t
	var rev TomList = EmptyConcTomTerm()
	for {
		c, ok := cur.(*ConcTomTermTomList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcTomTerm(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcTomTerm (through the hooks).
func (t *ConcTomTermTomList) Append(element TomTerm) TomList {
	var heads []TomTerm
	var cur TomList = t
	for {
		c, ok := cur.(*ConcTomTermTomList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res TomList
	if c, ok := cur.(*ConcTomTermTomList); ok && c.empty {
		res = ConsConcTomTerm(element, cur)
	} else {
		res = ConsConcTomTerm(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcTomTerm(heads[i], res)
	}
	return res
}

func (t *ConcTomTermTomList) CompareTo(o any) int {
	for {
		ao := o.(TomList)
		if ao == TomList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcTomTermTomList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcTomTermTomList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcTomTermTomList) CompareToLPO(o any) int {
	for {
		ao := o.(TomList)
		if ao == TomList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcTomTermTomList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcTomTermTomList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcTomTermTomList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []TomTerm
	var cur TomList = t
	for {
		c, ok := cur.(*ConcTomTermTomList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcTomTermTomList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcTomTermTomList is Java Gom's concTomTerm.fromTerm: an application of concTomTerm, or a
// list (of ToATerm), of convertible elements.
func fromTermConcTomTermTomList(trm aterm.ATerm, conv aterm.ATermConverter) (res TomList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concTomTerm" {
		elems := make([]TomTerm, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = TomTermFromTermConv(a, conv)
		}
		return MakeConcTomTerm(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concTomTerm (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []TomTerm
		for !list.IsEmpty() {
			elems = append(elems, TomTermFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcTomTerm(elems...), true
	}
	return nil, false
}
